SELECT id FROM xxl_job_log

	AND id > #{afterId} AND id <= #{maxId}

		AND job_group = #{jobGroup}


		AND job_id = #{jobId}


		AND trigger_time  <=  #{clearBeforeTime}


		AND id NOT in(
		SELECT id FROM(
		SELECT id FROM xxl_job_log AS t

			AND t.id <= #{maxId}

				AND t.job_group = #{jobGroup}


				AND t.job_id = #{jobId}


		ORDER BY t.trigger_time DESC, t.id DESC
		LIMIT 0, #{clearBeforeNum}
		) t1
		)


order by id asc
LIMIT #{pagesize}

